<script setup>
import { computed,ref,watch } from 'vue';
import { d10,fdate,ftime,lc,num } from '../../lib/client-info';
const props=defineProps({bundle:Object,metrics:Object});
const filter=ref('All'),page=ref(1),size=16;
const seconds=value=>String(value||'0:0:0').split(':').reduce((total,part,index)=>total+num(part)*[3600,60,1][index],0);
const sorted=computed(()=>props.bundle.appts.slice().sort((a,b)=>d10(b.appointment_date).localeCompare(d10(a.appointment_date))||seconds(b.appointment_time)-seconds(a.appointment_time)));
const statuses=computed(()=>['All',...new Set(sorted.value.map(row=>row.status||'Unknown'))]);
const filtered=computed(()=>sorted.value.filter(row=>filter.value==='All'||(row.status||'Unknown')===filter.value));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/size)));
const visible=computed(()=>filtered.value.slice((page.value-1)*size,page.value*size));
const upcoming=row=>d10(row.appointment_date)>=props.metrics.t&&!['cancelled','no show'].includes(lc(row.status));
const stats=computed(()=>[['📅','Total',sorted.value.length,''],['⏭️','Upcoming',sorted.value.filter(upcoming).length,sorted.value.some(upcoming)?'ok':''],['✅','Closed / checked out',sorted.value.filter(row=>['closed','checked out'].includes(lc(row.status))).length,'ok'],['🙈','No show',sorted.value.filter(row=>lc(row.status)==='no show').length,sorted.value.some(row=>lc(row.status)==='no show')?'neg':''],['✕','Cancelled',sorted.value.filter(row=>lc(row.status)==='cancelled').length,'warn']]);
function tone(row){const state=lc(row.status);return ['closed','checked out'].includes(state)?'ok':state==='cancelled'?'warn':state==='no show'?'neg':d10(row.appointment_date)>=props.metrics.t?'info':'mute';}
watch(filter,()=>{page.value=1;});watch(pages,value=>{page.value=Math.min(page.value,value);});
</script>
<template><div v-if="!sorted.length" class="c3-center c3-empty"><div class="c3-state-ic">📅</div><h3>No appointments</h3><p>Book the next visit from the Book appointment button.</p></div><div v-else><div class="c3-kpis"><div v-for="[icon,label,value,color] in stats" :key="label" class="c3-kpi"><span class="c3-kpi-ic">{{ icon }}</span><div><small>{{ label }}</small><b :class="color?'tone-'+color:''">{{ value }}</b></div></div></div><div class="c3-filters" data-appt-f><button v-for="value in statuses" :key="value" type="button" class="c3-fbtn" :class="{'is-on':filter===value}" :data-f="value" @click="filter=value">{{ value }} ({{ value==='All'?sorted.length:sorted.filter(row=>(row.status||'Unknown')===value).length }})</button></div><div class="c3-cards c3-c4" data-appt-grid><article v-for="row in visible" :key="row.name" class="c3-card c3-accent" :class="'tone-'+tone(row)"><header class="c3-card-h"><div><b>{{ d10(row.appointment_date)===metrics.t?'📍 Today':d10(row.appointment_date)>metrics.t?'⏭️ '+fdate(row.appointment_date):fdate(row.appointment_date) }}</b><small>🕐 {{ ftime(row.appointment_time)||'—' }}</small></div><span class="c3-pill" :class="'tone-'+tone(row)">{{ row.status||'—' }}</span></header><div class="c3-field f-green"><small>📌 Type</small><b>{{ row.appointment_type||'General' }}</b></div><div class="c3-field f-blue"><small>💆 Therapy</small><b>{{ row.therapy_type1||row.therapy_type||'—' }}</b></div><div class="c3-field"><small>🩺 Concern</small><b>{{ row.concern||'—' }}</b></div><div class="c3-grid c3-g2"><div class="c3-field f-amber"><small>👩‍⚕️ Practitioner</small><b>{{ row.practitioner_name||row.practitioner||'—' }}</b></div><div class="c3-field f-teal"><small>🏢 Branch</small><b>{{ row.branch||'—' }}</b></div></div><div v-if="row.call_back_status" class="c3-mini tone-warn">📞 Confirmation: {{ row.call_back_status }}</div><div v-if="row.service_room||row.service_unit" class="c3-mini">🚪 {{ [row.service_room,row.service_unit].filter(Boolean).join(' / ') }}</div></article></div><div v-if="pages>1" class="c3-pager-sm" data-appt-pager><button type="button" class="c3-btn c3-btn-sm" :disabled="page===1" @click="page--">Previous</button><span>Page {{ page }} of {{ pages }}</span><button type="button" class="c3-btn c3-btn-sm" :disabled="page===pages" @click="page++">Next</button></div></div></template>
